 var restored=state;object fresh=Activator.CreateInstance(type,true);var freshNodes=(List<SphereNetworkNode>)type.GetField("Nodes",F).GetValue(fresh);freshNodes.AddRange(nodes);var freshIds=(List<int>)type.GetField("Identities",F).GetValue(fresh);freshIds.AddRange(ids.Select(id=>id+1000));type.GetField("SphereCount",F).SetValue(fresh,nodes.Count);var resumed=(SphereNetworkState)type.GetMethod("Analyze",F).Invoke(fresh,new object[]{restored,SphereNetworkFormation.Triangle,SphereNetworkFormation.Triangle,SphereNetworkFormation.Line});A(resumed.DominantFormation.NodeIndexes.SequenceEqual(mainMembers),"new cache seeds restored exact formation indices despite new Unity IDs");
 nodes[2]=new SphereNetworkNode(new Vec2(30,30));nodes.RemoveAt(5);ids.RemoveAt(5);Analyze();A(state.DominantFormation.Type!=SphereNetworkFormation.Triangle,"moving sphere permits structural change");
 var result=new{status="PASS",checks,scope="actual native analysis cache: temporary disable/recovery, exact members, added node, following, manual swap, restored state, real movement; no saves changed"};Directory.CreateDirectory("Library/content-economy");File.WriteAllText("Library/content-economy/formations.json",Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
